{
  "summary": "This paper proposes an anatomy-aware multimodal framework for laryngopharyngeal cancer T-staging that integrates CT images and radiology reports. The framework uses an Anatomy-Structured Organ Graph (AOG), Organ-Anchored Cross-Modal Alignment (OCA), and Report-Enhanced Graph-Refinement (REG) to model anatomical relationships and align textual evidence with organ-specific features. The method demonstrates superior performance over state-of-the-art baselines and radiologist assessments in both binary and multi-class T-staging tasks.",
  "items": {
    "chk_problem": {
      "value": "Current clinical practice for laryngopharyngeal cancer T-staging relies on invasive biopsies, while CT-based staging is challenging due to complex tumor invasion patterns and limitations of existing computational methods.",
      "paper_quote": "Accurate T-staging is crucial for guiding personalized treatment strategies for laryngopharyngeal cancer. However, current clinical practice relies on invasive biopsy procedures, whereas CT-based staging remains challenging due to the complex patterns of tumor invasion.",
      "reason": null
    },
    "chk_method": {
      "value": "An anatomy-aware multimodal framework using an Anatomy-Structured Organ Graph (AOG), Organ-Anchored Cross-Modal Alignment (OCA), and Report-Enhanced Graph-Refinement (REG).",
      "paper_quote": "To address these issues, we propose an anatomy-aware multimodal framework that integrates organ-level CT context and radiology reports into a unified representation for laryngopharyngeal T-staging.",
      "reason": null
    },
    "chk_data": {
      "value": "A dataset of 656 patients from four medical centers, including CT scans and paired radiology reports, with 439 cases used for training and 217 for external testing.",
      "paper_quote": "To the best of our knowledge, we collect the first and largest dataset for CT-based laryngopharyngeal cancer T-staging, comprising 656 patients across four medical centers.",
      "reason": null
    },
    "chk_setup": {
      "value": "CT volumes resampled to 1mm3 isotropic spacing, resized to 128×128×128, and processed with a pre-trained organ segmentation model; experiments conducted using PyTorch on an NVIDIA H20 GPU.",
      "paper_quote": "All experiments are conducted using PyTorch [41] on an NVIDIA H20 GPU. For data preprocessing, all CT volumes are resampled to an isotropic spacing of 1mm3 and resized to a unified spatial dimension of 128×128×128.",
      "reason": null
    },
    "chk_primary_result": {
      "value": "Binary classification F1 score of 80.83% and accuracy of 81.53% on internal test set; F1 score of 76.46% and accuracy of 76.50% on external test set.",
      "paper_quote": "In the binary classification task (Early T1–T2 vs. Late T3–T4), our method achieves the highest performance on both internal and external test sets. For internal testing, we achieve an F1 score of 80.83% and accuracy of 81.53%, surpassing the second-best method MMI [3] (77.59% F1 score and 78.57% accuracy). On the external test set, our method maintains its leading position with an F1 score of 76.46% and accuracy of 76.50%.",
      "reason": null
    },
    "chk_secondary_result": {
      "value": "Three-class classification F1 score of 61.43% and accuracy of 63.33% on internal test set; F1 score of 60.27% and accuracy of 63.78% on external test set.",
      "paper_quote": "For the more challenging three-class classification task (T1, T2, T3–T4), our method also achieves consistent superior performance. On the internal test set, we achieve an F1 score of 61.43% and accuracy of 63.33%, showing notable improvements over MMBCD [1] (58.44% F1 score and 61.14% accuracy). The advantage is even more prominent on the external test set, where our method achieves an F1 score of 60.27% and accuracy of 63.78%.",
      "reason": null
    },
    "chk_baseline": {
      "value": "Compared against image-based methods (e.g., SwinViT, VDPF) and multimodal methods (e.g., CPAM, TGCAM, MMBCD, MMI), achieving superior performance in both binary and three-class classification tasks.",
      "paper_quote": "We compare the proposed method with image-based classification approaches, such as SwinViT [37], VDPF [38], MRSN [39], and several state-of-the-art multimodal learning methods (CPAM [5], TGCAM [2], MMBCD [1], LViT [4], MMI [3]). The results are summarized in Table II. Our method demonstrates superior performance across all experimental settings.",
      "reason": null
    },
    "chk_conclusion": {
      "value": "The proposed framework outperforms state-of-the-art baselines and radiologist assessments in T-staging tasks, offering improved interpretability and potential for real-world adoption.",
      "paper_quote": "Extensive experiments on the largest curated laryngopharyngeal cancer T-staging dataset, as well as on public benchmarks, demonstrated that our proposed framework consistently outperforms state-of-the-art unimodal and multimodal baselines in both binary and multi-class staging tasks, achieving notable gains over radiologist assessments.",
      "reason": null
    },
    "chk_limitation": {
      "value": "The framework depends on pre-trained organ segmentation models and may be affected by differences in imaging protocols and reporting styles across institutions.",
      "paper_quote": "First, the framework depends on a pre-trained organ segmentation model, whose performance may vary across imaging protocols and scanner vendors; validating or fine-tuning the segmentation model on site-specific data is advisable before deployment. Second, differences in reporting terminology and detail across institutions may affect the OCA and REG modules, though our cross-institutional evaluation suggests the learned cross-attention mechanism accommodates such variation reasonably well.",
      "reason": null
    }
  }
}
